  $ilitjson${"slug": "introduction-to-literary-studies", "title": "Introduction to Literary Studies", "description": "Introduce literature as an object of close attention, historical inquiry, interpretation, argument, and scholarly conversation. Topics cover close reading, literary terms and critical vocabulary, poetry, fiction and narrative technique, drama and performance, genre and convention, literary periods and historical context, book history and material texts, introductory theory, world literature and translation, canon and representation, secondary sources, literary analysis essays, MLA citation and scholarly practice, and a close reading portfolio.", "topics": [{"id": "a2f7ecb7-9195-45b5-b425-1086a2faf2a3", "type": "topic", "title": "Literary Study as a Discipline", "description": "Introduce literature as an object of close attention, historical inquiry, interpretation, argument, and scholarly conversation.", "children": [{"id": "950a4e29-0833-4e63-96f0-f7ef07c8ebc9", "type": "subtopic", "title": "What literary scholars do", "children": [{"id": "35fd0c1f-4a81-44a0-ab66-f32560b38bea", "type": "concept", "title": "Interpretation"}, {"id": "37f41717-2b0c-4023-9311-f2915604d08a", "type": "concept", "title": "Evidence-based claims"}, {"id": "4c56dfc0-e3f6-40c2-8089-d19958a835bc", "type": "concept", "title": "Scholarly debate"}, {"id": "166d9c5d-1e39-4a85-93ad-dcdca2959339", "type": "concept", "title": "Reading as method"}], "description": "Gist: Students begin by seeing literary study as careful reading plus historical, cultural, and argumentative inquiry."}, {"id": "6d6170f5-a1f0-466c-bff1-dadfbf8e255f", "type": "subtopic", "title": "Literature as art and institution", "children": [{"id": "ab8a0053-05cb-4b78-95f3-ca13d9fbf00d", "type": "concept", "title": "Authorship"}, {"id": "5dfb74e9-7991-4a20-8c10-5da1350a9b77", "type": "concept", "title": "Publication"}, {"id": "dac13f26-0930-44f6-a04f-a5ae6dcdbcac", "type": "concept", "title": "Reception"}, {"id": "5a5fac35-af4a-4fc8-bc6a-ff836a094f29", "type": "concept", "title": "Literary value"}], "description": "Gist: Literary works are aesthetic objects and also products of schools, publishers, markets, prizes, archives, and readers."}, {"id": "108603fd-fd20-4092-9ca4-a23109b2b1e2", "type": "subtopic", "title": "Habits of the literary reader", "children": [{"id": "7754333c-0e87-4513-bb5f-3b5ad46348cd", "type": "concept", "title": "Annotation"}, {"id": "8b435f42-1e49-4b0b-9f9a-35a0a634f347", "type": "concept", "title": "Rereading"}, {"id": "c8d2de0e-a023-4727-ad1e-ea53edecee7a", "type": "concept", "title": "Question-making"}, {"id": "ecd19bdc-4e06-4f03-809c-95aed262be99", "type": "concept", "title": "Pattern tracking"}], "description": "Gist: The course builds habits of attention that support every later English course."}]}, {"id": "dcc7b0aa-3ad5-4a60-9227-864b52e76003", "type": "topic", "title": "Critical Reading and Close Reading", "description": "Train students to notice how language, form, structure, and pattern produce meaning.", "children": [{"id": "85e08a80-c2f9-4c5a-9d83-96359f90588f", "type": "subtopic", "title": "Close attention to language", "children": [{"id": "a502bd0a-1e49-4b27-87da-2078918e4f4c", "type": "concept", "title": "Word choice"}, {"id": "4c110d0a-d1be-4fa3-ae60-b659dd602f28", "type": "concept", "title": "Syntax"}, {"id": "0890720c-a906-48b4-a6f8-5400fd7cf8fd", "type": "concept", "title": "Repetition"}, {"id": "dcc45d85-11b5-4bc2-88cd-6d410fcd5488", "type": "concept", "title": "Tone"}], "description": "Gist: Close reading teaches students to slow down and make claims from textual detail."}, {"id": "52be9771-91c0-4e02-bcee-aeffe8a6dcbc", "type": "subtopic", "title": "Pattern and structure", "children": [{"id": "320d6c9c-13af-4984-9312-22adae46fb6d", "type": "concept", "title": "Motifs"}, {"id": "8c625456-7543-484c-ab98-6b4594a26069", "type": "concept", "title": "Juxtaposition"}, {"id": "7cdfa002-bb63-46a1-8e1d-7ba67505eb75", "type": "concept", "title": "Turning points"}, {"id": "d551b8f0-2f76-45ff-acaa-e34468f0de1a", "type": "concept", "title": "Structural echoes"}], "description": "Gist: Students learn that meaning often emerges from recurrence, contrast, sequence, and arrangement."}, {"id": "c3d91d4d-d4e1-46d9-8764-6807824dea20", "type": "subtopic", "title": "From observation to interpretation", "children": [{"id": "1fc7a343-1fdc-4836-8a95-a3f37dd86c96", "type": "concept", "title": "Noticing"}, {"id": "9b5bc5d2-5721-482b-b92e-63ac90dabb4b", "type": "concept", "title": "Connecting"}, {"id": "adde120e-9e0c-444b-97c0-210201ccf26e", "type": "concept", "title": "Inferring"}, {"id": "3bf2d009-dc41-4a52-b0a5-346438359afa", "type": "concept", "title": "Explaining significance"}], "description": "Gist: Strong analysis turns noticed details into an arguable reading."}]}, {"id": "c9a0929c-1fb3-46d0-84bb-be51c2876fca", "type": "topic", "title": "Literary Terms, Devices, and Critical Vocabulary", "description": "Build a shared vocabulary for describing literary craft precisely and responsibly.", "children": [{"id": "860dcf55-5c55-4015-acc6-3fc87cee5780", "type": "subtopic", "title": "Core devices", "children": [{"id": "c4ed76cd-ca59-40f9-b74e-24cde7b171f6", "type": "concept", "title": "Metaphor"}, {"id": "76006cf4-7e75-40bb-908e-829d15d40a44", "type": "concept", "title": "Irony"}, {"id": "b15c44c8-8071-4335-9a53-91e214718d5e", "type": "concept", "title": "Symbol"}, {"id": "8c2295cf-cabd-4028-924e-50657fdd57e0", "type": "concept", "title": "Allusion"}], "description": "Gist: Shared vocabulary helps students describe what a text is doing instead of paraphrasing what it says."}, {"id": "64d5c81f-6d7a-465a-89ad-f10b9be7e199", "type": "subtopic", "title": "Form and structure terms", "children": [{"id": "110aedb4-4d1a-405e-b125-6126156e759c", "type": "concept", "title": "Stanza"}, {"id": "316e610c-c9db-4e5c-8342-50f2abcd691c", "type": "concept", "title": "Scene"}, {"id": "9f4f48d4-523f-4a6e-858f-89807aee12ad", "type": "concept", "title": "Narrator"}, {"id": "cbf546f0-f766-4501-aba4-96f389a70d5a", "type": "concept", "title": "Frame narrative"}], "description": "Gist: Formal vocabulary lets students connect craft choices to interpretation."}, {"id": "4c76ab68-902c-4247-965b-5c0ab019881a", "type": "subtopic", "title": "Responsible use of terms", "children": [{"id": "52254a4b-e2b3-457f-a611-01fa44998e0b", "type": "concept", "title": "Definition in context"}, {"id": "d52fb6e3-a370-4471-9908-7e0bf6e952ef", "type": "concept", "title": "Avoiding term lists"}, {"id": "2369a071-c556-448c-b527-ae3556f2719e", "type": "concept", "title": "Explaining effects"}, {"id": "312e58f8-f8e1-46be-9867-101e75862fc5", "type": "concept", "title": "Using examples"}], "description": "Gist: Terms are useful only when they clarify evidence and argument."}]}, {"id": "3168d3df-ae9d-4520-8aaa-5a76ffca9418", "type": "topic", "title": "Poetry: Form, Voice, Meter, and Figuration", "description": "Study poetry through sound, line, image, speaker, rhythm, form, and interpretive compression.", "children": [{"id": "5456fb0e-b446-4f8b-b14c-287be662e11a", "type": "subtopic", "title": "Speaker and voice", "children": [{"id": "fc45b198-fe69-4d50-90d0-b8ba94e371e7", "type": "concept", "title": "Speaker"}, {"id": "4c71af4c-8109-4a71-8576-c74895bb4281", "type": "concept", "title": "Persona"}, {"id": "8f0ad95d-12e9-4c54-aeca-80ce61566e04", "type": "concept", "title": "Address"}, {"id": "aa3b9daa-ef9b-4ece-a159-2cc6dcf01d0a", "type": "concept", "title": "Apostrophe"}], "description": "Gist: Poems often create a speaking position that may differ from the historical author."}, {"id": "ef780ff3-57a1-43e8-abde-848b1d539a12", "type": "subtopic", "title": "Sound and rhythm", "children": [{"id": "355f35ed-d04e-4624-b6d9-ce5020bf5784", "type": "concept", "title": "Meter"}, {"id": "ff0ef999-2692-495d-a572-90af4fef2f52", "type": "concept", "title": "Rhyme"}, {"id": "c8f787eb-367f-4906-aea8-d8a9b43f6d0c", "type": "concept", "title": "Alliteration"}, {"id": "51f8c380-336d-4332-b28d-e0a121ae5e67", "type": "concept", "title": "Enjambment"}], "description": "Gist: Poetic sound shapes memory, emphasis, emotion, and argument."}, {"id": "7fcbacfe-e73a-4ab9-9982-4caabf462d44", "type": "subtopic", "title": "Image, figure, and form", "children": [{"id": "66a32669-030d-446d-8288-a3b92892d14d", "type": "concept", "title": "Imagery"}, {"id": "480a37a8-7926-4723-8c91-23300695c285", "type": "concept", "title": "Simile and metaphor"}, {"id": "15fd9a62-a254-44e5-a4c3-26a2942dd0bd", "type": "concept", "title": "Sonnet"}, {"id": "5cfe193f-4a5c-4a47-92d6-2096991a9a8a", "type": "concept", "title": "Free verse"}], "description": "Gist: Poetry condenses meaning through figures, images, and inherited or invented forms."}]}, {"id": "deb19f39-a8cf-4558-b5d9-ff122fdb337d", "type": "topic", "title": "Fiction and Narrative Technique", "description": "Analyze how fiction organizes plot, narration, point of view, character, time, and setting.", "children": [{"id": "b1d9a0e5-a3e0-4f52-bd2e-64471eff31e4", "type": "subtopic", "title": "Narration and point of view", "children": [{"id": "1373497f-8a69-4d9f-abd0-00edbe695ee8", "type": "concept", "title": "First person"}, {"id": "54d948aa-7a0b-43f5-b186-4d22b354a184", "type": "concept", "title": "Third person"}, {"id": "2c9c2562-61fd-4d1f-84fb-3a9e71743d9d", "type": "concept", "title": "Free indirect discourse"}, {"id": "8648100d-abc3-4884-aad4-c18315830d81", "type": "concept", "title": "Unreliable narration"}], "description": "Gist: Narrative voice controls what readers know, trust, question, and feel."}, {"id": "616c88f0-d142-4017-8f99-cb26337094fe", "type": "subtopic", "title": "Plot and time", "children": [{"id": "0b11ab83-ed42-4c7b-b6df-2fc463f03f5c", "type": "concept", "title": "Chronology"}, {"id": "e0e1728d-f92d-455c-908e-1af20e312e6e", "type": "concept", "title": "Flashback"}, {"id": "138503b0-a5e9-4515-8ad9-dc667295d360", "type": "concept", "title": "Foreshadowing"}, {"id": "4ca2ec4e-fcb2-413b-8dcd-a013c423e0f8", "type": "concept", "title": "Narrative gaps"}], "description": "Gist: Fiction organizes events into meaningful patterns rather than merely listing what happened."}, {"id": "c8954217-dee2-47e0-88d1-ca9486137809", "type": "subtopic", "title": "Character, setting, and world", "children": [{"id": "42dcc2fc-37db-4ce4-aa3c-151f89c444e3", "type": "concept", "title": "Characterization"}, {"id": "93e54e81-2a77-4148-9441-2a9459a52244", "type": "concept", "title": "Conflict"}, {"id": "3ae6641a-a489-4553-bf72-c12c9fe8ec7f", "type": "concept", "title": "Place"}, {"id": "579a83be-8fbf-478f-ab6e-7c46666836e4", "type": "concept", "title": "Social world"}], "description": "Gist: Characters and settings carry social, psychological, historical, and symbolic meanings."}]}, {"id": "d453e5c5-c17f-4388-b19d-89ce2d753390", "type": "topic", "title": "Drama, Performance, and Theatrical Form", "description": "Read drama as text, performance, speech, embodiment, staging, conflict, and social action.", "children": [{"id": "67b82cfc-ae3f-4dc8-a96e-abb6f3e6ede3", "type": "subtopic", "title": "Drama as text and performance", "children": [{"id": "b340d40c-893c-4540-8b94-e45fd4923ce3", "type": "concept", "title": "Dialogue"}, {"id": "cb4a5930-809c-4f77-b333-0112f96c6d0b", "type": "concept", "title": "Stage directions"}, {"id": "4a1a5fd9-db45-4b83-8639-ab15ac8aac8a", "type": "concept", "title": "Blocking"}, {"id": "8564faef-2ab7-4e43-965d-6afc5265695d", "type": "concept", "title": "Audience"}], "description": "Gist: Plays are written to be spoken, embodied, staged, and interpreted in performance."}, {"id": "33d3de22-b7a5-4367-a431-b573a21fde87", "type": "subtopic", "title": "Dramatic structure", "children": [{"id": "302d92e9-0cc9-48b4-9c0e-5b209d9a773e", "type": "concept", "title": "Exposition"}, {"id": "0434bdf3-fb46-4273-b07e-6236db1aa075", "type": "concept", "title": "Rising action"}, {"id": "40d511fa-523e-43a4-b80b-e4ff5b5def0f", "type": "concept", "title": "Climax"}, {"id": "891f8ed4-ea3b-471d-b50e-3209a4afd3ca", "type": "concept", "title": "Resolution and ambiguity"}], "description": "Gist: Drama creates meaning through conflict, pacing, scenes, entrances, exits, and turning points."}, {"id": "18963f1f-f996-4a81-b2a9-da1ea598e376", "type": "subtopic", "title": "Performance interpretation", "children": [{"id": "4e1680ca-a39e-4b9b-9ebd-13fb4d64c25a", "type": "concept", "title": "Casting"}, {"id": "879aa0df-b296-431e-866c-fbf14b543ae5", "type": "concept", "title": "Gesture"}, {"id": "fea88d26-ed7b-4777-83fe-77021c25fccd", "type": "concept", "title": "Set and costume"}, {"id": "26defe63-c9a6-4c7f-9ba3-b006270e1113", "type": "concept", "title": "Performance history"}], "description": "Gist: Students learn that staging choices can change how a play means."}]}, {"id": "6dacd7ed-71e8-4d3a-abb8-a6be251ce357", "type": "topic", "title": "Genre, Form, and Convention", "description": "Understand genre as a system of expectations that writers inherit, revise, mix, and resist.", "children": [{"id": "4a8f7980-4b56-4ac8-b9f2-da0cb1db90bb", "type": "subtopic", "title": "Genre expectations", "children": [{"id": "92f1eb41-0d88-466e-931e-71741ea23ee0", "type": "concept", "title": "Lyric"}, {"id": "d00fc94d-554b-496a-bdc7-9a749dd2d0be", "type": "concept", "title": "Epic"}, {"id": "d664c03f-a832-484c-a8d1-477db315f39f", "type": "concept", "title": "Tragedy"}, {"id": "8544198f-754f-46de-b543-fb14fa83cfcb", "type": "concept", "title": "Novel"}], "description": "Gist: Genres teach readers what to expect, and writers often create meaning by fulfilling or disrupting those expectations."}, {"id": "f108d9d7-512b-44e0-a203-48608068ed96", "type": "subtopic", "title": "Convention and innovation", "children": [{"id": "6d882c78-0809-47e3-a31a-9fa5b6ad958e", "type": "concept", "title": "Parody"}, {"id": "2d334ba6-d663-4149-ac69-08048539f1d7", "type": "concept", "title": "Hybrid genres"}, {"id": "5380e2d3-60af-43c3-944d-1959601b02fd", "type": "concept", "title": "Experiment"}, {"id": "0362287d-a39e-477c-8b95-af1c2a977bcc", "type": "concept", "title": "Intertextuality"}], "description": "Gist: Literary history changes when writers revise inherited forms."}, {"id": "3425f9e4-cb73-4e9d-bd87-351f8e9f2884", "type": "subtopic", "title": "Genre and culture", "children": [{"id": "8f90e80f-8929-4178-9490-0860df369cb8", "type": "concept", "title": "Periodicals"}, {"id": "7f9a565d-6c4f-4fab-8e4f-f389e80d4404", "type": "concept", "title": "Theater"}, {"id": "006b8ee0-eac2-446f-a54a-ba02b51bb6dc", "type": "concept", "title": "Publishing markets"}, {"id": "0ada1643-f90a-40ed-b2d8-84f12d9df882", "type": "concept", "title": "Digital genres"}], "description": "Gist: Genres are tied to institutions, audiences, technologies, and social needs."}]}, {"id": "63f1f476-4972-4dc5-9b79-7085d01744a4", "type": "topic", "title": "Literary Periods and Historical Context", "description": "Connect texts to major literary periods, cultural change, historical events, and changing ideas of authorship.", "children": [{"id": "e57714fe-92f3-4688-b62c-4aedf378d4ff", "type": "subtopic", "title": "Period overview", "children": [{"id": "2c3f750e-db72-4441-9b50-eb8db29e4536", "type": "concept", "title": "Medieval"}, {"id": "8358522d-2fb3-4ca5-a94b-760c6c06a4c3", "type": "concept", "title": "Early modern"}, {"id": "689db9f5-4fc3-4634-8fb3-bf825c7fb9a1", "type": "concept", "title": "Romantic and Victorian"}, {"id": "02006064-16be-4e3b-813f-3325294876a3", "type": "concept", "title": "Modern and contemporary"}], "description": "Gist: A broad period map gives students orientation without reducing texts to background facts."}, {"id": "7e1b8248-3e05-44b3-a6dd-488316f86026", "type": "subtopic", "title": "Contextual reading", "children": [{"id": "2161246c-a248-428f-9257-1ef6ae256a53", "type": "concept", "title": "Politics"}, {"id": "00e61024-4db9-4abe-9627-4f72aff56a26", "type": "concept", "title": "Religion"}, {"id": "6cc2072c-4dd9-465b-a81f-65ef38456a29", "type": "concept", "title": "Science"}, {"id": "1e9bc0ee-7873-4633-aa84-daee16382a43", "type": "concept", "title": "Labor and empire"}], "description": "Gist: Historical context helps students ask better questions about language, form, and social meaning."}, {"id": "bb7eee28-9f7c-4b09-9c85-24d277e0b0ea", "type": "subtopic", "title": "Periodization as argument", "children": [{"id": "692a2df8-3434-4cb0-a622-05ee7a02e574", "type": "concept", "title": "Continuity and rupture"}, {"id": "276e84e4-1754-47cc-9b31-5a7968e2f588", "type": "concept", "title": "Canon formation"}, {"id": "9a92d3d3-5dee-4aa0-92ae-36d777ccb723", "type": "concept", "title": "National traditions"}, {"id": "544e3f43-021e-47bd-9f9d-d15bad8b2fb1", "type": "concept", "title": "Global timelines"}], "description": "Gist: Students learn that period labels are useful but contested scholarly tools."}]}, {"id": "b40a26ef-7bb6-43af-acd8-4bc4a5f6bee3", "type": "topic", "title": "Book History, Archives, and Material Texts", "description": "Introduce literature as material and social production shaped by manuscripts, print, publishing, circulation, and archives.", "children": [{"id": "68089413-3475-4047-8b6d-fc80c6309fd8", "type": "subtopic", "title": "Material texts", "children": [{"id": "854fb806-6b78-4730-98ed-0cc126852c02", "type": "concept", "title": "Manuscripts"}, {"id": "e4ea2722-1a89-49de-a539-6b1e1d6d1f83", "type": "concept", "title": "Print editions"}, {"id": "0a5b4086-09ad-4c79-8f58-c7ae5669e286", "type": "concept", "title": "Paratexts"}, {"id": "4e1cd48a-b0db-4696-9448-1e96e294f66b", "type": "concept", "title": "Digital texts"}], "description": "Gist: Literary works reach readers through material forms that affect interpretation."}, {"id": "619d8cf4-4133-4964-828f-c8d6f1ab7fc4", "type": "subtopic", "title": "Publishing and circulation", "children": [{"id": "bf3a14e3-6643-4248-89d8-89dac9cecd8b", "type": "concept", "title": "Publishers"}, {"id": "541b393c-3408-48c5-9b22-bfff4cf278e4", "type": "concept", "title": "Serial publication"}, {"id": "87abcf0a-3308-4e0b-8686-55312fbba21d", "type": "concept", "title": "Audience and reception"}, {"id": "de041886-40a7-46c0-9cc2-cde0f438265e", "type": "concept", "title": "Censorship"}], "description": "Gist: Books move through markets, institutions, censorship, libraries, and communities."}, {"id": "fd74ad46-7602-4611-afcc-1d0390bbf5ed", "type": "subtopic", "title": "Archives and evidence", "children": [{"id": "758cd360-9ab9-4252-b867-e7386ab0ae5a", "type": "concept", "title": "Special collections"}, {"id": "22fc7af9-0c37-447c-8243-6cc06e923476", "type": "concept", "title": "Letters and drafts"}, {"id": "00b57e2d-791f-4151-83bf-27e91c61892c", "type": "concept", "title": "Ephemera"}, {"id": "45906872-88b9-49e9-a64c-9863f6bffa23", "type": "concept", "title": "Archival silence"}], "description": "Gist: Archives introduce students to primary sources, preservation, absence, and research ethics."}]}, {"id": "0b006b87-f056-4f97-a785-7c1775e29b47", "type": "topic", "title": "Introduction to Literary Theory and Critical Approaches", "description": "Give students accessible entry points into major interpretive frameworks without overwhelming the foundation course.", "children": [{"id": "076952c5-6991-46ee-b821-accfc0449720", "type": "subtopic", "title": "Why theory matters", "children": [{"id": "7e2838e7-8f6f-4809-b370-9ca0aedb8ce8", "type": "concept", "title": "Formalist questions"}, {"id": "261b0a0d-21de-4299-8da0-776a24d9f168", "type": "concept", "title": "Historical questions"}, {"id": "d079eceb-2357-4582-80c9-24ff786fd746", "type": "concept", "title": "Ideological questions"}, {"id": "de7494c0-f4c6-4449-9eb7-9e8a5d410f5c", "type": "concept", "title": "Reader questions"}], "description": "Gist: Theory gives students explicit tools for asking different kinds of questions about the same text."}, {"id": "0be73ab1-81c2-40c6-be83-d495c79dcf15", "type": "subtopic", "title": "Accessible critical schools", "children": [{"id": "b12a4f68-8d2f-4fb0-ae9f-f10815a59b89", "type": "concept", "title": "Feminist and gender criticism"}, {"id": "aa6fc9a2-1ee0-4098-a8b8-0abf03f358ed", "type": "concept", "title": "Marxist criticism"}, {"id": "cf247e5e-dc1c-42a6-842f-1b7a722ff861", "type": "concept", "title": "Postcolonial criticism"}, {"id": "2131ac2e-9daf-41e2-a6c0-a1023632ed6a", "type": "concept", "title": "Psychoanalytic criticism"}], "description": "Gist: Students get introductory contact with major approaches they will meet later in the major."}, {"id": "edc65c63-68c3-40d6-839c-a8587df4901c", "type": "subtopic", "title": "Theory as method, not jargon", "children": [{"id": "84819aab-1d10-4f17-a14c-8f6a8fd5b7ca", "type": "concept", "title": "Key concepts"}, {"id": "c380987a-a374-4ec9-977a-1f685cc9b373", "type": "concept", "title": "Application to passages"}, {"id": "ddb357e9-b65a-4fbb-91e0-1ecd91ee396a", "type": "concept", "title": "Method limits"}, {"id": "3f37f06f-bdf1-45bb-b9ee-b3276b564e49", "type": "concept", "title": "Comparing readings"}], "description": "Gist: The goal is practical interpretive use, not memorizing abstract names."}]}, {"id": "7884349f-b6e5-4b77-bf23-a4568ad26d0e", "type": "topic", "title": "World Literature, Translation, and Comparative Reading", "description": "Expand literary study beyond a single national tradition through translation, circulation, comparison, and global contexts.", "children": [{"id": "a5acea13-f8bb-41de-aac6-38b0ee856668", "type": "subtopic", "title": "Translation awareness", "children": [{"id": "990e7cae-768e-41fe-84ca-5847e0b0d7e6", "type": "concept", "title": "Translator's notes"}, {"id": "36d73861-28f2-4a95-844a-fd369efc3b03", "type": "concept", "title": "Multiple translations"}, {"id": "2f3fa358-3e51-4587-9201-38765ec79b5e", "type": "concept", "title": "Untranslatable terms"}, {"id": "1d1ba540-0921-418f-a289-7871fbc7ccf5", "type": "concept", "title": "Cultural context"}], "description": "Gist: Translation is interpretation, so students learn to ask what translation choices make visible or obscure."}, {"id": "b6c0a2ef-fd7e-40fa-9c8e-85e88d4b09a4", "type": "subtopic", "title": "Comparative methods", "children": [{"id": "03f6d628-ac5c-4250-bf7b-2fdb884462dc", "type": "concept", "title": "Motifs across traditions"}, {"id": "cf2a1b0e-a881-4a10-9027-a8e79d3ffe7c", "type": "concept", "title": "Genre migration"}, {"id": "68f43e19-be71-401e-a966-e7e4ea51c8b8", "type": "concept", "title": "Influence and adaptation"}, {"id": "cea6e10f-8f84-425a-968e-1743707fc495", "type": "concept", "title": "Reception across borders"}], "description": "Gist: Comparative reading reveals patterns across language, form, period, and culture."}, {"id": "f873617d-4b33-47de-a9c8-5a7b884baade", "type": "subtopic", "title": "Global circulation", "children": [{"id": "18b4dbe9-2f7e-4df8-981a-073f7f37166d", "type": "concept", "title": "World literature debates"}, {"id": "038ff1ca-6de7-4d02-a541-471f745d39d5", "type": "concept", "title": "Diaspora"}, {"id": "2fae6263-f704-45ff-9322-03a870d30ee8", "type": "concept", "title": "Colonial and postcolonial contexts"}, {"id": "d9820ecf-f7b2-4eb9-9b54-e3d777207e06", "type": "concept", "title": "Literary prizes"}], "description": "Gist: Literature travels through empire, migration, diaspora, education, publishing, and media."}]}, {"id": "f5cdd6ca-4fc6-4a93-81cd-a7e1e3d6eb12", "type": "topic", "title": "Canon, Power, Identity, and Representation", "description": "Teach students to ask how literary value, inclusion, exclusion, identity, and power shape reading practices.", "children": [{"id": "4ad63f93-5166-4d7f-9c35-630b5ef4e7a6", "type": "subtopic", "title": "Canon formation", "children": [{"id": "9d8a0e1a-b987-42c6-bfb5-abb4515f7afe", "type": "concept", "title": "Anthologies"}, {"id": "84566766-1b7c-41c5-9e4d-5d7d38a2115e", "type": "concept", "title": "School curricula"}, {"id": "d1da5b2d-ebf8-44f2-9f46-ac6278b50232", "type": "concept", "title": "Prizes"}, {"id": "b7272511-482e-4dd9-ba7f-c5dc9ff01751", "type": "concept", "title": "Recovery work"}], "description": "Gist: Students ask how some texts become central and others become marginal or invisible."}, {"id": "2fdc595f-6d3b-4ae0-87b1-841a4a391fa7", "type": "subtopic", "title": "Identity and representation", "children": [{"id": "caad91ec-d332-4e2a-940a-69f1342f3740", "type": "concept", "title": "Stereotype"}, {"id": "4388514b-8914-4e5d-b22d-575956f32c61", "type": "concept", "title": "Voice"}, {"id": "5f3dccb9-b068-45c8-ada5-e9973b81bb86", "type": "concept", "title": "Point of view"}, {"id": "eb4f4386-b608-42d2-bebb-56307032b21b", "type": "concept", "title": "Self-representation"}], "description": "Gist: Literary texts participate in constructing race, gender, sexuality, class, nation, disability, and religion."}, {"id": "f90232b6-dfac-4039-8d45-954228903cd0", "type": "subtopic", "title": "Ethical reading", "children": [{"id": "048b8551-61ca-4abc-96fa-614321cb5d11", "type": "concept", "title": "Historical humility"}, {"id": "4ce9caa4-8fc6-45b0-9b62-5bf1f253971b", "type": "concept", "title": "Avoiding presentism"}, {"id": "e835c623-8c49-4854-b5e9-f24b98a55cb5", "type": "concept", "title": "Respectful terminology"}, {"id": "56855544-d71b-4bb5-aaeb-2f179e394ce8", "type": "concept", "title": "Accountable claims"}], "description": "Gist: Interpretation carries responsibilities toward authors, contexts, communities, and evidence."}]}, {"id": "1c81c512-6007-464f-9e0f-5d72c966cc20", "type": "topic", "title": "Secondary Sources and Literary Research", "description": "Help students enter scholarly conversations through databases, sources, annotations, and research questions.", "children": [{"id": "7069be11-555b-46fc-8a94-60e962e51006", "type": "subtopic", "title": "Finding scholarship", "children": [{"id": "b6b1958a-4ba2-48c1-9284-af95b9274694", "type": "concept", "title": "MLA International Bibliography"}, {"id": "b50712f9-f9f9-485a-a7a9-40d5f6bf6ddd", "type": "concept", "title": "JSTOR"}, {"id": "3322c8ea-0b8e-4ecb-8b1d-a7f1d0d48a33", "type": "concept", "title": "Project MUSE"}, {"id": "037efbf0-a0be-4f65-b629-4ef60a0da513", "type": "concept", "title": "Library catalogs"}], "description": "Gist: Students learn how literary research begins with databases, bibliographies, and good search terms."}, {"id": "dce6f8dd-1ccd-4f31-88a9-7f00a4c9e48b", "type": "subtopic", "title": "Using secondary sources", "children": [{"id": "d80f74bc-fd6b-4d7b-ae53-607596f509c0", "type": "concept", "title": "Summary"}, {"id": "ce00edce-cb21-49ba-a9be-f2511d253ccb", "type": "concept", "title": "Quotation"}, {"id": "fb84d346-614f-453b-97f9-9ea4ee5dbbf8", "type": "concept", "title": "Synthesis"}, {"id": "4d95eba2-2e40-47a9-889b-71ba98b7146f", "type": "concept", "title": "Source conversation"}], "description": "Gist: Scholarly sources should sharpen, complicate, or challenge a student's own reading."}, {"id": "7ecbcf4f-b22f-4fba-aac6-c0af5e741518", "type": "subtopic", "title": "Research questions", "children": [{"id": "8d2be408-29ba-4e6b-8363-46b32cbe4938", "type": "concept", "title": "Scope"}, {"id": "5e1ef148-30e1-45ff-9e24-c48792a0fa82", "type": "concept", "title": "Significance"}, {"id": "0d2e870b-9bd4-4762-b492-997cce57ed7e", "type": "concept", "title": "Feasibility"}, {"id": "7e1dd650-6ba4-4c36-b59c-3872725171fa", "type": "concept", "title": "Scholarly stakes"}], "description": "Gist: A strong research question turns curiosity into a focused project."}]}, {"id": "14ef0105-4c55-46ba-9e63-072b54cecb32", "type": "topic", "title": "Writing Literary Analysis Essays", "description": "Develop arguable, evidence-based literary essays through thesis, close reading, structure, and revision.", "children": [{"id": "c6adcebb-5a01-424d-8800-59177e99450f", "type": "subtopic", "title": "Thesis and argument", "children": [{"id": "365b8b03-569e-4047-a46d-8b1e5443baec", "type": "concept", "title": "Specific thesis"}, {"id": "49111f83-fd1a-4c58-8cbf-f8c3f7195b28", "type": "concept", "title": "Stakes"}, {"id": "c5fdecc8-2037-4b2f-89f6-6eb4e34af52f", "type": "concept", "title": "Evidence map"}, {"id": "e10fa550-4d9f-486d-b843-5274dd52e920", "type": "concept", "title": "Counter-reading"}], "description": "Gist: Literary essays need arguable claims about how and why a text means."}, {"id": "ebc64cc5-bdf2-4651-b3b7-874e736c1c5f", "type": "subtopic", "title": "Evidence and close reading", "children": [{"id": "eca3085e-6c32-441f-bbc1-51bc340bc074", "type": "concept", "title": "Signal phrases"}, {"id": "2e13a199-9d81-41ef-8095-8e01755cbc3c", "type": "concept", "title": "Quotation integration"}, {"id": "edba243e-07dd-4d97-b425-f74aa1190de4", "type": "concept", "title": "Line-level analysis"}, {"id": "7ef002cb-3a36-4b28-89ed-262ef72c4be6", "type": "concept", "title": "Commentary"}], "description": "Gist: Quotations must be framed, analyzed, and tied back to the argument."}, {"id": "788a5272-9010-4dca-9e97-241abba1ec58", "type": "subtopic", "title": "Essay structure and revision", "children": [{"id": "0230442f-864d-408c-9057-c8c54295b3a7", "type": "concept", "title": "Introductions"}, {"id": "5cdd76bb-6cbc-49d8-a3f9-efdf844049a6", "type": "concept", "title": "Paragraph movement"}, {"id": "7becd7ec-7502-4eb4-8203-76a61a4c5a85", "type": "concept", "title": "Transitions"}, {"id": "93090e63-9927-4633-b39d-6d7e53d9bce2", "type": "concept", "title": "Global revision"}], "description": "Gist: Students learn to build essays that develop rather than repeat a claim."}]}, {"id": "b642e596-a046-46b2-b9fc-99f06196f88c", "type": "topic", "title": "MLA Citation, Academic Integrity, and Scholarly Practice", "description": "Build responsible documentation habits and ethical participation in academic literary study.", "children": [{"id": "37dda7a8-8a5d-4500-ab62-2a73dc754db9", "type": "subtopic", "title": "MLA style", "children": [{"id": "1ae71d9f-b7f2-4c0c-b8af-be8804bfce97", "type": "concept", "title": "In-text citations"}, {"id": "fae378fd-c052-412e-b6ca-5b2ef13da116", "type": "concept", "title": "Works Cited"}, {"id": "c5ee0d1c-d6bc-4008-b6ea-a5070a743db3", "type": "concept", "title": "Poetry and drama citation"}, {"id": "dbf62bc0-d0c7-4a14-969b-c16b23abadbe", "type": "concept", "title": "Editions and translations"}], "description": "Gist: MLA documentation teaches students how literary scholars cite texts and sources."}, {"id": "34ba2890-ffe0-4ee7-87b1-ca6d79fd58dd", "type": "subtopic", "title": "Academic integrity", "children": [{"id": "bff0d2fc-ec59-4c65-bbe3-f6e7eab86455", "type": "concept", "title": "Attribution"}, {"id": "cff445af-17a0-440e-9b05-93f02b7742e8", "type": "concept", "title": "Paraphrase"}, {"id": "14d0c687-49c9-4a19-86de-aaa0dd4b2f59", "type": "concept", "title": "Common knowledge"}, {"id": "620fb147-a08e-4fd2-af4f-fc0660feeb75", "type": "concept", "title": "AI and writing transparency"}], "description": "Gist: Integrity is more than avoiding plagiarism; it is fair representation of sources and labor."}, {"id": "3add583f-6494-41ae-8385-469c07de5d66", "type": "subtopic", "title": "Scholarly professionalism", "children": [{"id": "75c1525f-fb5c-4ca3-a01c-44f7cc380edc", "type": "concept", "title": "Formatting"}, {"id": "9d5d1d0b-1c29-4033-86a5-b8f3b80790a5", "type": "concept", "title": "Revision records"}, {"id": "1ddda86c-4dea-421e-b027-a28a6ddc526e", "type": "concept", "title": "Peer review etiquette"}, {"id": "22f28ca5-bd26-4798-b0c4-f8b3e09ec007", "type": "concept", "title": "Submission standards"}], "description": "Gist: Students practice habits that make their work legible to academic readers."}]}, {"id": "d614b24e-e605-4c84-877b-d49aa2ed00c0", "type": "topic", "title": "Capstone: Close Reading Portfolio and Critical Essay", "description": "Synthesize reading, research, argument, revision, citation, and reflection in a polished introductory portfolio.", "children": [{"id": "dd152a0c-0793-4233-940b-e259dc31cab7", "type": "subtopic", "title": "Portfolio selection", "children": [{"id": "596e1569-bf7e-40b8-922c-1ca4d2585219", "type": "concept", "title": "Annotations"}, {"id": "0b4d4e29-b776-43bb-aed0-b97ecdfec3b8", "type": "concept", "title": "Response papers"}, {"id": "5441ab37-71fb-42cf-b1e6-af59f32155df", "type": "concept", "title": "Drafts"}, {"id": "db49c30b-ac32-453f-9b34-ac3021da4333", "type": "concept", "title": "Revision evidence"}], "description": "Gist: The portfolio lets students show growth across reading notes, short analyses, drafts, and revised work."}, {"id": "2e1cf113-ea0a-4462-b93c-f9211e39047b", "type": "subtopic", "title": "Final critical essay", "children": [{"id": "cf6160d1-51d8-45d3-bf0d-641b394afe2b", "type": "concept", "title": "Research question"}, {"id": "8fe2c85f-0efd-499a-a6ee-8557c8b1613f", "type": "concept", "title": "Thesis"}, {"id": "fa6fb7a6-412f-4932-a9bb-907c24d67c7d", "type": "concept", "title": "Primary evidence"}, {"id": "4280c99b-9375-4371-9dc5-fde79b1128a6", "type": "concept", "title": "Secondary source integration"}], "description": "Gist: The essay synthesizes close reading, context, source use, and argument."}, {"id": "ace22435-ab33-4169-b31b-2bb561bbc0cc", "type": "subtopic", "title": "Reflective introduction", "children": [{"id": "91d94bc3-e760-496c-9f97-a4dab2cfd855", "type": "concept", "title": "Learning outcomes"}, {"id": "16d15470-2ac2-45d6-8a5b-e702df0cb78e", "type": "concept", "title": "Method reflection"}, {"id": "f07397e0-1e22-4c7f-a016-6c88fce7e831", "type": "concept", "title": "Strengths and next steps"}, {"id": "87d149f7-f6db-41fb-b65f-f2f70c5207fa", "type": "concept", "title": "Future reading plans"}], "description": "Gist: Reflection helps students name what they have learned and how they will transfer it to future literary study."}]}], "dbBacked": true}$ilitjson$::jsonb,
  true,
  false,
  'course',
  'public'
where not exists (
  select 1 from public.learning_paths where slug = 'introduction-to-literary-studies'
);

update public.learning_paths
set
  title = 'Introduction to Literary Studies',
  goal = 'Introduction to Literary Studies',
  summary = 'Introduce literature as an object of close attention, historical inquiry, interpretation, argument, and scholarly conversation. Topics cover close reading, literary terms and critical vocabulary, poetry, fiction and narrative technique, drama and performance, genre and convention, literary periods and historical context, book history and material texts, introductory theory, world literature and translation, canon and representation, secondary sources, literary analysis essays, MLA citation and scholarly practice, and a close reading portfolio.',
  data = $ilitjson${"slug": "introduction-to-literary-studies", "title": "Introduction to Literary Studies", "description": "Introduce literature as an object of close attention, historical inquiry, interpretation, argument, and scholarly conversation. Topics cover close reading, literary terms and critical vocabulary, poetry, fiction and narrative technique, drama and performance, genre and convention, literary periods and historical context, book history and material texts, introductory theory, world literature and translation, canon and representation, secondary sources, literary analysis essays, MLA citation and scholarly practice, and a close reading portfolio.", "topics": [{"id": "a2f7ecb7-9195-45b5-b425-1086a2faf2a3", "type": "topic", "title": "Literary Study as a Discipline", "description": "Introduce literature as an object of close attention, historical inquiry, interpretation, argument, and scholarly conversation.", "children": [{"id": "950a4e29-0833-4e63-96f0-f7ef07c8ebc9", "type": "subtopic", "title": "What literary scholars do", "children": [{"id": "35fd0c1f-4a81-44a0-ab66-f32560b38bea", "type": "concept", "title": "Interpretation"}, {"id": "37f41717-2b0c-4023-9311-f2915604d08a", "type": "concept", "title": "Evidence-based claims"}, {"id": "4c56dfc0-e3f6-40c2-8089-d19958a835bc", "type": "concept", "title": "Scholarly debate"}, {"id": "166d9c5d-1e39-4a85-93ad-dcdca2959339", "type": "concept", "title": "Reading as method"}], "description": "Gist: Students begin by seeing literary study as careful reading plus historical, cultural, and argumentative inquiry."}, {"id": "6d6170f5-a1f0-466c-bff1-dadfbf8e255f", "type": "subtopic", "title": "Literature as art and institution", "children": [{"id": "ab8a0053-05cb-4b78-95f3-ca13d9fbf00d", "type": "concept", "title": "Authorship"}, {"id": "5dfb74e9-7991-4a20-8c10-5da1350a9b77", "type": "concept", "title": "Publication"}, {"id": "dac13f26-0930-44f6-a04f-a5ae6dcdbcac", "type": "concept", "title": "Reception"}, {"id": "5a5fac35-af4a-4fc8-bc6a-ff836a094f29", "type": "concept", "title": "Literary value"}], "description": "Gist: Literary works are aesthetic objects and also products of schools, publishers, markets, prizes, archives, and readers."}, {"id": "108603fd-fd20-4092-9ca4-a23109b2b1e2", "type": "subtopic", "title": "Habits of the literary reader", "children": [{"id": "7754333c-0e87-4513-bb5f-3b5ad46348cd", "type": "concept", "title": "Annotation"}, {"id": "8b435f42-1e49-4b0b-9f9a-35a0a634f347", "type": "concept", "title": "Rereading"}, {"id": "c8d2de0e-a023-4727-ad1e-ea53edecee7a", "type": "concept", "title": "Question-making"}, {"id": "ecd19bdc-4e06-4f03-809c-95aed262be99", "type": "concept", "title": "Pattern tracking"}], "description": "Gist: The course builds habits of attention that support every later English course."}]}, {"id": "dcc7b0aa-3ad5-4a60-9227-864b52e76003", "type": "topic", "title": "Critical Reading and Close Reading", "description": "Train students to notice how language, form, structure, and pattern produce meaning.", "children": [{"id": "85e08a80-c2f9-4c5a-9d83-96359f90588f", "type": "subtopic", "title": "Close attention to language", "children": [{"id": "a502bd0a-1e49-4b27-87da-2078918e4f4c", "type": "concept", "title": "Word choice"}, {"id": "4c110d0a-d1be-4fa3-ae60-b659dd602f28", "type": "concept", "title": "Syntax"}, {"id": "0890720c-a906-48b4-a6f8-5400fd7cf8fd", "type": "concept", "title": "Repetition"}, {"id": "dcc45d85-11b5-4bc2-88cd-6d410fcd5488", "type": "concept", "title": "Tone"}], "description": "Gist: Close reading teaches students to slow down and make claims from textual detail."}, {"id": "52be9771-91c0-4e02-bcee-aeffe8a6dcbc", "type": "subtopic", "title": "Pattern and structure", "children": [{"id": "320d6c9c-13af-4984-9312-22adae46fb6d", "type": "concept", "title": "Motifs"}, {"id": "8c625456-7543-484c-ab98-6b4594a26069", "type": "concept", "title": "Juxtaposition"}, {"id": "7cdfa002-bb63-46a1-8e1d-7ba67505eb75", "type": "concept", "title": "Turning points"}, {"id": "d551b8f0-2f76-45ff-acaa-e34468f0de1a", "type": "concept", "title": "Structural echoes"}], "description": "Gist: Students learn that meaning often emerges from recurrence, contrast, sequence, and arrangement."}, {"id": "c3d91d4d-d4e1-46d9-8764-6807824dea20", "type": "subtopic", "title": "From observation to interpretation", "children": [{"id": "1fc7a343-1fdc-4836-8a95-a3f37dd86c96", "type": "concept", "title": "Noticing"}, {"id": "9b5bc5d2-5721-482b-b92e-63ac90dabb4b", "type": "concept", "title": "Connecting"}, {"id": "adde120e-9e0c-444b-97c0-210201ccf26e", "type": "concept", "title": "Inferring"}, {"id": "3bf2d009-dc41-4a52-b0a5-346438359afa", "type": "concept", "title": "Explaining significance"}], "description": "Gist: Strong analysis turns noticed details into an arguable reading."}]}, {"id": "c9a0929c-1fb3-46d0-84bb-be51c2876fca", "type": "topic", "title": "Literary Terms, Devices, and Critical Vocabulary", "description": "Build a shared vocabulary for describing literary craft precisely and responsibly.", "children": [{"id": "860dcf55-5c55-4015-acc6-3fc87cee5780", "type": "subtopic", "title": "Core devices", "children": [{"id": "c4ed76cd-ca59-40f9-b74e-24cde7b171f6", "type": "concept", "title": "Metaphor"}, {"id": "76006cf4-7e75-40bb-908e-829d15d40a44", "type": "concept", "title": "Irony"}, {"id": "b15c44c8-8071-4335-9a53-91e214718d5e", "type": "concept", "title": "Symbol"}, {"id": "8c2295cf-cabd-4028-924e-50657fdd57e0", "type": "concept", "title": "Allusion"}], "description": "Gist: Shared vocabulary helps students describe what a text is doing instead of paraphrasing what it says."}, {"id": "64d5c81f-6d7a-465a-89ad-f10b9be7e199", "type": "subtopic", "title": "Form and structure terms", "children": [{"id": "110aedb4-4d1a-405e-b125-6126156e759c", "type": "concept", "title": "Stanza"}, {"id": "316e610c-c9db-4e5c-8342-50f2abcd691c", "type": "concept", "title": "Scene"}, {"id": "9f4f48d4-523f-4a6e-858f-89807aee12ad", "type": "concept", "title": "Narrator"}, {"id": "cbf546f0-f766-4501-aba4-96f389a70d5a", "type": "concept", "title": "Frame narrative"}], "description": "Gist: Formal vocabulary lets students connect craft choices to interpretation."}, {"id": "4c76ab68-902c-4247-965b-5c0ab019881a", "type": "subtopic", "title": "Responsible use of terms", "children": [{"id": "52254a4b-e2b3-457f-a611-01fa44998e0b", "type": "concept", "title": "Definition in context"}, {"id": "d52fb6e3-a370-4471-9908-7e0bf6e952ef", "type": "concept", "title": "Avoiding term lists"}, {"id": "2369a071-c556-448c-b527-ae3556f2719e", "type": "concept", "title": "Explaining effects"}, {"id": "312e58f8-f8e1-46be-9867-101e75862fc5", "type": "concept", "title": "Using examples"}], "description": "Gist: Terms are useful only when they clarify evidence and argument."}]}, {"id": "3168d3df-ae9d-4520-8aaa-5a76ffca9418", "type": "topic", "title": "Poetry: Form, Voice, Meter, and Figuration", "description": "Study poetry through sound, line, image, speaker, rhythm, form, and interpretive compression.", "children": [{"id": "5456fb0e-b446-4f8b-b14c-287be662e11a", "type": "subtopic", "title": "Speaker and voice", "children": [{"id": "fc45b198-fe69-4d50-90d0-b8ba94e371e7", "type": "concept", "title": "Speaker"}, {"id": "4c71af4c-8109-4a71-8576-c74895bb4281", "type": "concept", "title": "Persona"}, {"id": "8f0ad95d-12e9-4c54-aeca-80ce61566e04", "type": "concept", "title": "Address"}, {"id": "aa3b9daa-ef9b-4ece-a159-2cc6dcf01d0a", "type": "concept", "title": "Apostrophe"}], "description": "Gist: Poems often create a speaking position that may differ from the historical author."}, {"id": "ef780ff3-57a1-43e8-abde-848b1d539a12", "type": "subtopic", "title": "Sound and rhythm", "children": [{"id": "355f35ed-d04e-4624-b6d9-ce5020bf5784", "type": "concept", "title": "Meter"}, {"id": "ff0ef999-2692-495d-a572-90af4fef2f52", "type": "concept", "title": "Rhyme"}, {"id": "c8f787eb-367f-4906-aea8-d8a9b43f6d0c", "type": "concept", "title": "Alliteration"}, {"id": "51f8c380-336d-4332-b28d-e0a121ae5e67", "type": "concept", "title": "Enjambment"}], "description": "Gist: Poetic sound shapes memory, emphasis, emotion, and argument."}, {"id": "7fcbacfe-e73a-4ab9-9982-4caabf462d44", "type": "subtopic", "title": "Image, figure, and form", "children": [{"id": "66a32669-030d-446d-8288-a3b92892d14d", "type": "concept", "title": "Imagery"}, {"id": "480a37a8-7926-4723-8c91-23300695c285", "type": "concept", "title": "Simile and metaphor"}, {"id": "15fd9a62-a254-44e5-a4c3-26a2942dd0bd", "type": "concept", "title": "Sonnet"}, {"id": "5cfe193f-4a5c-4a47-92d6-2096991a9a8a", "type": "concept", "title": "Free verse"}], "description": "Gist: Poetry condenses meaning through figures, images, and inherited or invented forms."}]}, {"id": "deb19f39-a8cf-4558-b5d9-ff122fdb337d", "type": "topic", "title": "Fiction and Narrative Technique", "description": "Analyze how fiction organizes plot, narration, point of view, character, time, and setting.", "children": [{"id": "b1d9a0e5-a3e0-4f52-bd2e-64471eff31e4", "type": "subtopic", "title": "Narration and point of view", "children": [{"id": "1373497f-8a69-4d9f-abd0-00edbe695ee8", "type": "concept", "title": "First person"}, {"id": "54d948aa-7a0b-43f5-b186-4d22b354a184", "type": "concept", "title": "Third person"}, {"id": "2c9c2562-61fd-4d1f-84fb-3a9e71743d9d", "type": "concept", "title": "Free indirect discourse"}, {"id": "8648100d-abc3-4884-aad4-c18315830d81", "type": "concept", "title": "Unreliable narration"}], "description": "Gist: Narrative voice controls what readers know, trust, question, and feel."}, {"id": "616c88f0-d142-4017-8f99-cb26337094fe", "type": "subtopic", "title": "Plot and time", "children": [{"id": "0b11ab83-ed42-4c7b-b6df-2fc463f03f5c", "type": "concept", "title": "Chronology"}, {"id": "e0e1728d-f92d-455c-908e-1af20e312e6e", "type": "concept", "title": "Flashback"}, {"id": "138503b0-a5e9-4515-8ad9-dc667295d360", "type": "concept", "title": "Foreshadowing"}, {"id": "4ca2ec4e-fcb2-413b-8dcd-a013c423e0f8", "type": "concept", "title": "Narrative gaps"}], "description": "Gist: Fiction organizes events into meaningful patterns rather than merely listing what happened."}, {"id": "c8954217-dee2-47e0-88d1-ca9486137809", "type": "subtopic", "title": "Character, setting, and world", "children": [{"id": "42dcc2fc-37db-4ce4-aa3c-151f89c444e3", "type": "concept", "title": "Characterization"}, {"id": "93e54e81-2a77-4148-9441-2a9459a52244", "type": "concept", "title": "Conflict"}, {"id": "3ae6641a-a489-4553-bf72-c12c9fe8ec7f", "type": "concept", "title": "Place"}, {"id": "579a83be-8fbf-478f-ab6e-7c46666836e4", "type": "concept", "title": "Social world"}], "description": "Gist: Characters and settings carry social, psychological, historical, and symbolic meanings."}]}, {"id": "d453e5c5-c17f-4388-b19d-89ce2d753390", "type": "topic", "title": "Drama, Performance, and Theatrical Form", "description": "Read drama as text, performance, speech, embodiment, staging, conflict, and social action.", "children": [{"id": "67b82cfc-ae3f-4dc8-a96e-abb6f3e6ede3", "type": "subtopic", "title": "Drama as text and performance", "children": [{"id": "b340d40c-893c-4540-8b94-e45fd4923ce3", "type": "concept", "title": "Dialogue"}, {"id": "cb4a5930-809c-4f77-b333-0112f96c6d0b", "type": "concept", "title": "Stage directions"}, {"id": "4a1a5fd9-db45-4b83-8639-ab15ac8aac8a", "type": "concept", "title": "Blocking"}, {"id": "8564faef-2ab7-4e43-965d-6afc5265695d", "type": "concept", "title": "Audience"}], "description": "Gist: Plays are written to be spoken, embodied, staged, and interpreted in performance."}, {"id": "33d3de22-b7a5-4367-a431-b573a21fde87", "type": "subtopic", "title": "Dramatic structure", "children": [{"id": "302d92e9-0cc9-48b4-9c0e-5b209d9a773e", "type": "concept", "title": "Exposition"}, {"id": "0434bdf3-fb46-4273-b07e-6236db1aa075", "type": "concept", "title": "Rising action"}, {"id": "40d511fa-523e-43a4-b80b-e4ff5b5def0f", "type": "concept", "title": "Climax"}, {"id": "891f8ed4-ea3b-471d-b50e-3209a4afd3ca", "type": "concept", "title": "Resolution and ambiguity"}], "description": "Gist: Drama creates meaning through conflict, pacing, scenes, entrances, exits, and turning points."}, {"id": "18963f1f-f996-4a81-b2a9-da1ea598e376", "type": "subtopic", "title": "Performance interpretation", "children": [{"id": "4e1680ca-a39e-4b9b-9ebd-13fb4d64c25a", "type": "concept", "title": "Casting"}, {"id": "879aa0df-b296-431e-866c-fbf14b543ae5", "type": "concept", "title": "Gesture"}, {"id": "fea88d26-ed7b-4777-83fe-77021c25fccd", "type": "concept", "title": "Set and costume"}, {"id": "26defe63-c9a6-4c7f-9ba3-b006270e1113", "type": "concept", "title": "Performance history"}], "description": "Gist: Students learn that staging choices can change how a play means."}]}, {"id": "6dacd7ed-71e8-4d3a-abb8-a6be251ce357", "type": "topic", "title": "Genre, Form, and Convention", "description": "Understand genre as a system of expectations that writers inherit, revise, mix, and resist.", "children": [{"id": "4a8f7980-4b56-4ac8-b9f2-da0cb1db90bb", "type": "subtopic", "title": "Genre expectations", "children": [{"id": "92f1eb41-0d88-466e-931e-71741ea23ee0", "type": "concept", "title": "Lyric"}, {"id": "d00fc94d-554b-496a-bdc7-9a749dd2d0be", "type": "concept", "title": "Epic"}, {"id": "d664c03f-a832-484c-a8d1-477db315f39f", "type": "concept", "title": "Tragedy"}, {"id": "8544198f-754f-46de-b543-fb14fa83cfcb", "type": "concept", "title": "Novel"}], "description": "Gist: Genres teach readers what to expect, and writers often create meaning by fulfilling or disrupting those expectations."}, {"id": "f108d9d7-512b-44e0-a203-48608068ed96", "type": "subtopic", "title": "Convention and innovation", "children": [{"id": "6d882c78-0809-47e3-a31a-9fa5b6ad958e", "type": "concept", "title": "Parody"}, {"id": "2d334ba6-d663-4149-ac69-08048539f1d7", "type": "concept", "title": "Hybrid genres"}, {"id": "5380e2d3-60af-43c3-944d-1959601b02fd", "type": "concept", "title": "Experiment"}, {"id": "0362287d-a39e-477c-8b95-af1c2a977bcc", "type": "concept", "title": "Intertextuality"}], "description": "Gist: Literary history changes when writers revise inherited forms."}, {"id": "3425f9e4-cb73-4e9d-bd87-351f8e9f2884", "type": "subtopic", "title": "Genre and culture", "children": [{"id": "8f90e80f-8929-4178-9490-0860df369cb8", "type": "concept", "title": "Periodicals"}, {"id": "7f9a565d-6c4f-4fab-8e4f-f389e80d4404", "type": "concept", "title": "Theater"}, {"id": "006b8ee0-eac2-446f-a54a-ba02b51bb6dc", "type": "concept", "title": "Publishing markets"}, {"id": "0ada1643-f90a-40ed-b2d8-84f12d9df882", "type": "concept", "title": "Digital genres"}], "description": "Gist: Genres are tied to institutions, audiences, technologies, and social needs."}]}, {"id": "63f1f476-4972-4dc5-9b79-7085d01744a4", "type": "topic", "title": "Literary Periods and Historical Context", "description": "Connect texts to major literary periods, cultural change, historical events, and changing ideas of authorship.", "children": [{"id": "e57714fe-92f3-4688-b62c-4aedf378d4ff", "type": "subtopic", "title": "Period overview", "children": [{"id": "2c3f750e-db72-4441-9b50-eb8db29e4536", "type": "concept", "title": "Medieval"}, {"id": "8358522d-2fb3-4ca5-a94b-760c6c06a4c3", "type": "concept", "title": "Early modern"}, {"id": "689db9f5-4fc3-4634-8fb3-bf825c7fb9a1", "type": "concept", "title": "Romantic and Victorian"}, {"id": "02006064-16be-4e3b-813f-3325294876a3", "type": "concept", "title": "Modern and contemporary"}], "description": "Gist: A broad period map gives students orientation without reducing texts to background facts."}, {"id": "7e1b8248-3e05-44b3-a6dd-488316f86026", "type": "subtopic", "title": "Contextual reading", "children": [{"id": "2161246c-a248-428f-9257-1ef6ae256a53", "type": "concept", "title": "Politics"}, {"id": "00e61024-4db9-4abe-9627-4f72aff56a26", "type": "concept", "title": "Religion"}, {"id": "6cc2072c-4dd9-465b-a81f-65ef38456a29", "type": "concept", "title": "Science"}, {"id": "1e9bc0ee-7873-4633-aa84-daee16382a43", "type": "concept", "title": "Labor and empire"}], "description": "Gist: Historical context helps students ask better questions about language, form, and social meaning."}, {"id": "bb7eee28-9f7c-4b09-9c85-24d277e0b0ea", "type": "subtopic", "title": "Periodization as argument", "children": [{"id": "692a2df8-3434-4cb0-a622-05ee7a02e574", "type": "concept", "title": "Continuity and rupture"}, {"id": "276e84e4-1754-47cc-9b31-5a7968e2f588", "type": "concept", "title": "Canon formation"}, {"id": "9a92d3d3-5dee-4aa0-92ae-36d777ccb723", "type": "concept", "title": "National traditions"}, {"id": "544e3f43-021e-47bd-9f9d-d15bad8b2fb1", "type": "concept", "title": "Global timelines"}], "description": "Gist: Students learn that period labels are useful but contested scholarly tools."}]}, {"id": "b40a26ef-7bb6-43af-acd8-4bc4a5f6bee3", "type": "topic", "title": "Book History, Archives, and Material Texts", "description": "Introduce literature as material and social production shaped by manuscripts, print, publishing, circulation, and archives.", "children": [{"id": "68089413-3475-4047-8b6d-fc80c6309fd8", "type": "subtopic", "title": "Material texts", "children": [{"id": "854fb806-6b78-4730-98ed-0cc126852c02", "type": "concept", "title": "Manuscripts"}, {"id": "e4ea2722-1a89-49de-a539-6b1e1d6d1f83", "type": "concept", "title": "Print editions"}, {"id": "0a5b4086-09ad-4c79-8f58-c7ae5669e286", "type": "concept", "title": "Paratexts"}, {"id": "4e1cd48a-b0db-4696-9448-1e96e294f66b", "type": "concept", "title": "Digital texts"}], "description": "Gist: Literary works reach readers through material forms that affect interpretation."}, {"id": "619d8cf4-4133-4964-828f-c8d6f1ab7fc4", "type": "subtopic", "title": "Publishing and circulation", "children": [{"id": "bf3a14e3-6643-4248-89d8-89dac9cecd8b", "type": "concept", "title": "Publishers"}, {"id": "541b393c-3408-48c5-9b22-bfff4cf278e4", "type": "concept", "title": "Serial publication"}, {"id": "87abcf0a-3308-4e0b-8686-55312fbba21d", "type": "concept", "title": "Audience and reception"}, {"id": "de041886-40a7-46c0-9cc2-cde0f438265e", "type": "concept", "title": "Censorship"}], "description": "Gist: Books move through markets, institutions, censorship, libraries, and communities."}, {"id": "fd74ad46-7602-4611-afcc-1d0390bbf5ed", "type": "subtopic", "title": "Archives and evidence", "children": [{"id": "758cd360-9ab9-4252-b867-e7386ab0ae5a", "type": "concept", "title": "Special collections"}, {"id": "22fc7af9-0c37-447c-8243-6cc06e923476", "type": "concept", "title": "Letters and drafts"}, {"id": "00b57e2d-791f-4151-83bf-27e91c61892c", "type": "concept", "title": "Ephemera"}, {"id": "45906872-88b9-49e9-a64c-9863f6bffa23", "type": "concept", "title": "Archival silence"}], "description": "Gist: Archives introduce students to primary sources, preservation, absence, and research ethics."}]}, {"id": "0b006b87-f056-4f97-a785-7c1775e29b47", "type": "topic", "title": "Introduction to Literary Theory and Critical Approaches", "description": "Give students accessible entry points into major interpretive frameworks without overwhelming the foundation course.", "children": [{"id": "076952c5-6991-46ee-b821-accfc0449720", "type": "subtopic", "title": "Why theory matters", "children": [{"id": "7e2838e7-8f6f-4809-b370-9ca0aedb8ce8", "type": "concept", "title": "Formalist questions"}, {"id": "261b0a0d-21de-4299-8da0-776a24d9f168", "type": "concept", "title": "Historical questions"}, {"id": "d079eceb-2357-4582-80c9-24ff786fd746", "type": "concept", "title": "Ideological questions"}, {"id": "de7494c0-f4c6-4449-9eb7-9e8a5d410f5c", "type": "concept", "title": "Reader questions"}], "description": "Gist: Theory gives students explicit tools for asking different kinds of questions about the same text."}, {"id": "0be73ab1-81c2-40c6-be83-d495c79dcf15", "type": "subtopic", "title": "Accessible critical schools", "children": [{"id": "b12a4f68-8d2f-4fb0-ae9f-f1